+const { useState, useRef } = React;
+
+const QUESTIONS = [
+  {
+    id: "q1",
+    prompt: "Which of the following are statically typed languages?",
+    help: "Select all that apply. Statically typed languages check types at compile time.",
+    options: [
+      { id: "q1a", label: "Java", value: "java" },
+      { id: "q1b", label: "Python", value: "python" },
+      { id: "q1c", label: "Rust", value: "rust" },
+      { id: "q1d", label: "JavaScript", value: "javascript" },
+    ],
+    correct: ["java", "rust"],
+  },
+  {
+    id: "q2",
+    prompt: "Which languages run primarily on the JVM?",
+    options: [
+      { id: "q2a", label: "Kotlin", value: "kotlin" },
+      { id: "q2b", label: "Scala", value: "scala" },
+      { id: "q2c", label: "Go", value: "go" },
+      { id: "q2d", label: "Swift", value: "swift" },
+    ],
+    correct: ["kotlin", "scala"],
+  },
+  {
+    id: "q3",
+    prompt: "Which of these are functional programming languages?",
+    options: [
+      { id: "q3a", label: "Haskell", value: "haskell" },
+      { id: "q3b", label: "Elixir", value: "elixir" },
+      { id: "q3c", label: "C", value: "c" },
+      { id: "q3d", label: "COBOL", value: "cobol" },
+    ],
+    correct: ["haskell", "elixir"],
+  },
+];
+
+function CheckboxQuestion({ question, selected, onToggle }) {
+  const helpId = question.help ? `${question.id}-help` : undefined;
+  return (
+    <div className="form-field">
+      <fieldset aria-describedby={helpId}>
+        <legend>{question.prompt}</legend>
+        {question.help && <p id={helpId} className="q-help">{question.help}</p>}
+        <div className="options">
+          {question.options.map((opt) => (
+            <div className="option" key={opt.id}>
+              <input
+                type="checkbox"
+                id={opt.id}
+                name={question.id}
+                value={opt.value}
+                checked={selected.includes(opt.value)}
+                onChange={() => onToggle(question.id, opt.value)}
+              />
+              <label htmlFor={opt.id}>{opt.label}</label>
+            </div>
+          ))}
+        </div>
+      </fieldset>
+    </div>
+  );
+}
+
+function Quiz() {
+  const [answers, setAnswers] = useState(
+    Object.fromEntries(QUESTIONS.map((q) => [q.id, []]))
+  );
+  const [result, setResult] = useState(null);
+  const resultRef = useRef(null);
+
+  const toggle = (qId, value) => {
+    setAnswers((prev) => {
+      const cur = prev[qId];
+      const next = cur.includes(value)
+        ? cur.filter((v) => v !== value)
+        : [...cur, value];
+      return { ...prev, [qId]: next };
+    });
+  };
+
+  const handleSubmit = (e) => {
+    e.preventDefault();
+    let score = 0;
+    QUESTIONS.forEach((q) => {
+      const sel = [...answers[q.id]].sort().join(",");
+      const correct = [...q.correct].sort().join(",");
+      if (sel === correct) score += 1;
+    });
+    setResult({ score, total: QUESTIONS.length });
+    setTimeout(() => {
+      if (resultRef.current) resultRef.current.focus();
+    }, 0);
+  };
+
+  return (
+    <>
+      <header className="quiz-header">
+        <h1>Computer Languages Quiz</h1>
+        <p>Three multi-select questions. Pick every option you think applies.</p>
+      </header>
+      <form noValidate onSubmit={handleSubmit}>
+        {QUESTIONS.map((q) => (
+          <CheckboxQuestion
+            key={q.id}
+            question={q}
+            selected={answers[q.id]}
+            onToggle={toggle}
+          />
+        ))}
+        <div className="actions">
+          <button type="submit">Submit answers</button>
+        </div>
+        {result && (
+          <div
+            className="results"
+            role="status"
+            aria-live="polite"
+            tabIndex="-1"
+            ref={resultRef}
+          >
+            <h2>Results</h2>
+            <p>
+              You scored <span className="score">{result.score} of {result.total}</span> questions correct.
+            </p>
+            <p>A question is correct only when every right option (and no wrong ones) is selected.</p>
+          </div>
+        )}
+      </form>
+    </>
+  );
+}
+
+const root = ReactDOM.createRoot(document.getElementById("root"));
+root.render(<Quiz />);
+
')

